"""Original English skill practice; not textbook-derived or an official model test."""
import json, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
D=ROOT/'content/question-bank/class-6/english-1st'
passage='''Every Wednesday, Class Six spends twenty minutes caring for a small garden behind the school library. Their teacher, Ms Rahman, helped them make a plan, but the pupils chose the plants. They planted spinach, beans and marigolds in three separate beds. A narrow path lets everyone walk between the beds without stepping on young plants.

At first, the children carried water in open buckets. Much of it spilled on the path. Rupa suggested using old bottles with small holes in their caps. The bottles helped the pupils water the roots slowly. The teacher checked that the bottles had no sharp edges before anyone used them.

The class keeps a notebook beside the library window. Each group records the weather, the plants' growth and the work it has done. When some leaves turned yellow, the pupils did not immediately add more water. They asked their teacher for help and compared their notes.

After the first harvest, the class shared the vegetables with the school kitchen. The children were proud, not because their garden was large, but because they had learned to work together and use resources carefully.'''
activities=[]
def add(id,kind,instruction,**kw):
 activities.append(dict(id=id,kind=kind,instruction=instruction,marks=None,**kw))
mcqs=[
 ('Where is the garden?',['Behind the school library','Beside a railway station','Inside the kitchen','In front of a market'],'A','The first sentence locates the garden behind the library.'),
 ('Who chose the plants?',['The school cook','The pupils','A visitor','The librarian alone'],'B','The teacher helped with planning, but the pupils chose the plants.'),
 ('Why is there a narrow path?',['To store the notebooks','To collect the harvest','To avoid stepping on young plants','To grow only flowers'],'C','The path provides a route between the beds without damaging plants.'),
 ('What problem did the open buckets cause?',['They blocked the library window','They made the vegetables yellow','They had no handles','Water spilled on the path'],'D','The passage explicitly describes spilled water.'),
 ('How did the bottles help?',['They watered the roots slowly','They measured the weather','They replaced the notebook','They kept every leaf dry'],'A','Small holes allowed slow watering near the roots.'),
 ('What did the pupils do when leaves turned yellow?',['They pulled out every plant','They sought help and compared notes','They stopped keeping records','They immediately added more water'],'B','They asked the teacher and used their records; no diagnosis is supplied.'),
 ('Which lesson best fits the passage?',['A large garden always gives more learning','Flowers are more useful than vegetables','Cooperation and careful use of resources matter','Children should use tools without checking them'],'C','The final paragraph states what made the class proud.')]
add('reading-mcq','reading-mcq','Read passage P1 and choose the best answer.',passageId='P1',items=[dict(id=f'm{i}',question=q,options=dict(zip('ABCD',o)),answer=a,explanation=e) for i,(q,o,a,e) in enumerate(mcqs,1)])
qa=[('How often does the class care for the garden?','The class cares for it every Wednesday, for twenty minutes.',['every Wednesday']),('Name the three kinds of plants in the garden.','The pupils planted spinach, beans and marigolds.',['spinach','beans','marigolds']),('How was the teacher involved in the bottle idea?','She checked that the bottles had no sharp edges before the pupils used them.',['checked','sharp edges']),('What does each group record?','Each group records the weather, plant growth and the work it has done.',['weather','growth','work']),('Why were the children proud after the harvest?','They were proud because they had learned to work together and use resources carefully.',['work together','resources'])]
add('reading-answers','reading-short-answer','Answer using information from passage P1. Equivalent accurate wording is acceptable.',passageId='P1',items=[dict(id=f'a{i}',question=q,modelAnswer=a,requiredIdeas=r) for i,(q,a,r) in enumerate(qa,1)])
add('cloze','contextual-gap','Complete this account using the words in the box. Use each word once.',passageId='P1',wordBox=['roots','notebook','Wednesday','kitchen','path'],text='The class works in the garden every (a) ____. A narrow (b) ____ protects the young plants from being stepped on. The bottles deliver water slowly to the (c) ____. Groups write observations in a (d) ____. The first vegetables went to the school (e) ____.',answers={'a':'Wednesday','b':'path','c':'roots','d':'notebook','e':'kitchen'})
add('vocabulary','vocabulary-in-context','Give a word or phrase with the requested meaning in the context of P1.',passageId='P1',items=[dict(word=w,request=r,acceptedAnswers=a) for w,r,a in [('separate','a similar meaning',['distinct','not joined together']),('narrow','an opposite meaning',['wide','broad']),('slowly','an opposite meaning',['quickly','rapidly']),('carefully','a similar meaning',['with care','cautiously']),('proud','a similar meaning',['pleased with what they had achieved','feeling satisfaction in their achievement'])]])
add('information-transfer','information-transfer','Complete the missing cells from P1.',passageId='P1',columns=['Person or group','Action'],rows=[['Ms Rahman','(a)'],['(b)','Suggested bottles with holes in the caps'],['Each group','(c)'],['(d)','Received the first vegetables'],['Class Six','Cared for the garden every (e)']],answers={'a':'Helped make a plan; also checked bottle edges. Either action is acceptable.','b':'Rupa','c':'Recorded weather, plant growth and completed work','d':'The school kitchen','e':'Wednesday'})
add('true-false','true-false','State true or false according to P1. Correct each false statement.',passageId='P1',items=[dict(statement=s,answer=a,correction=c) for s,a,c in [('The pupils chose the plants.',True,None),('The garden had three separate beds.',True,None),('The pupils first used closed bottles to carry water.',False,'They first carried water in open buckets.'),('Yellow leaves made the class immediately add more water.',False,'They asked the teacher for help and compared their notes instead of immediately adding water.'),('The size of the garden was the reason for the children\'s pride.',False,'They were proud of cooperation and careful resource use, not the garden\'s size.')]])
add('summary','summary','Write a short summary of P1 in your own words. Include the main activity, an improvement and the central lesson. No official word limit is asserted.',passageId='P1',modelAnswer='A Class Six group cares for a school garden with guidance from its teacher. The pupils reduce wasted water by using checked bottles and keep records to understand changes in the plants. They share their first vegetables with the school kitchen. The project teaches them cooperation and responsible use of resources.',assessment=['Includes gardening as a shared class project','Mentions an evidence-based example of careful resource use or recording','Retains the lesson of cooperation and responsibility','Uses connected, accurate sentences rather than copying the entire passage'],unacceptableInferences=['A specific disease caused the yellow leaves','The class sold its vegetables','The teacher chose all the plants'])
add('matching','sentence-matching','Match each beginning to one ending. Use each ending once.',beginnings={'1':'To save water,','2':'Before using the bottles,','3':'To monitor the garden,','4':'When the leaves changed colour,','5':'After the harvest,'},endings={'A':'the groups recorded their observations.','B':'the pupils asked for guidance.','C':'the class shared vegetables with the kitchen.','D':'Rupa proposed slow watering through small holes.','E':'the teacher checked their edges.'},answers={'1':'D','2':'E','3':'A','4':'B','5':'C'})
add('rearranging','sentence-rearranging','Arrange these sentences into a connected account. Underlined connectors are not required; use the time clues.',sentences={'A':'After collecting them, the class washed and sorted the containers.','B':'With the planting finished, a group put the pots on a safe shelf.','C':'First, the teacher asked everyone to collect suitable used containers.','D':'A week later, the first shoots appeared in the pots on the shelf.','E':'Before filling the clean containers, the teacher checked them for damage.','F':'After filling them, the children planted seeds in the soil.','G':'Seeing the shoots, they began measuring their height each morning.','H':'Once the check was complete, the children filled the containers with soil.'},answer=['C','A','E','H','F','B','D','G'],explanation='The chain is collecting → washing → checking → filling → planting → placing → shoots appearing → measuring. The explicit references establish that order.')
add('story','story-completion','Complete this story in a coherent way: On the way home, Mina found a small bag on a bench. She looked around, but no one was nearby. Then she noticed a school badge on the bag ...',modelAnswer='Mina recognised the badge of a nearby school. She did not open the bag or take it home. Instead, she went to the school office and told the teacher on duty where she had found it. The teacher kept the bag safely and contacted the class teachers. Soon a worried pupil arrived with his mother. Before handing it over, the teacher asked them to describe the bag and its contents. Their description matched. The boy thanked Mina because his exercise books were inside. Mina was glad that she had asked a responsible adult for help. She returned home and told her family what had happened.',assessment=['Continues the given opening without contradiction','Has connected events and a plausible ending','Uses consistent narrative tense and clear references','Avoids encouraging unsafe contact with strangers'],note='Original model completion. Other coherent, safe endings are acceptable; this is not a memorisation-only answer.')
add('paragraph','paragraph-writing','Write a paragraph about working together at school. Explain one shared task, how responsibilities can be divided and why listening matters.',modelAnswer='Working together at school helps us learn from one another. Last month, our class organised a small reading corner. We first discussed what we needed and listened to different suggestions. Some pupils collected suitable books, while others cleaned the shelf with help from a teacher. Another group made labels so that readers could find stories easily. We divided the work according to our abilities, not according to who was the loudest. When two friends disagreed about the labels, they explained their ideas and chose a clear design together. We also made a simple rule about returning books after reading. The corner was small, but everyone had a chance to contribute. I learned that teamwork requires patience, fairness and responsibility. A shared task becomes easier when we respect others and ask for help when necessary.',assessment=['Addresses a shared school task with relevant details','Explains responsibilities and listening','Presents connected ideas as a paragraph','Uses age-appropriate vocabulary, grammar and punctuation'],note='No official word count or marks assigned until guidance is verified. Personal examples may differ.')
add('dialogue','dialogue-writing','Write a short dialogue between two classmates planning a reading corner. Include a suggestion, a question, a polite response and an agreed plan.',modelAnswer=[{'speaker':'Asha','line':'Could we make a reading corner in our classroom?'},{'speaker':'Rafi','line':'That sounds useful. Where could we put the books?'},{'speaker':'Asha','line':'There is a spare shelf beside the window. We should ask our teacher first.'},{'speaker':'Rafi','line':'Good idea. How will we collect suitable books?'},{'speaker':'Asha','line':'We can invite classmates to lend books they are willing to share.'},{'speaker':'Rafi','line':'Shall we label them so that none gets lost?'},{'speaker':'Asha','line':'Yes. We can keep a notebook showing who borrows each book.'},{'speaker':'Rafi','line':'I can help make the labels. Would you speak to the teacher with me?'},{'speaker':'Asha','line':'Certainly. Let us ask after class today.'},{'speaker':'Rafi','line':'Agreed. Then we can discuss the plan with everyone.'}],assessment=['Speakers respond meaningfully to one another','Includes suggestion, question, polite response and agreement','Maintains a clear purpose and natural sequence','Uses readable speaker labels and appropriate language'],note='Alternative names and wording are acceptable. Do not require verbatim reproduction.')
pack=dict(id='class6-english1-original-skills-001',category='Class 6',subject='English 1st Paper',status='ORIGINAL_PRACTICE_DRAFT_NOT_REGISTERED',teacherApproved=False,officialDistributionVerified=False,fullModelTest=False,totalMarks=None,durationMinutes=None,provenance=dict(origin='Original educational practice authored for this repository; not extracted from the NCTB textbook or commercial guide.',textbookSeenPassage=False,sourcePage=None),passages=[dict(id='P1',title='Learning in the School Garden',text=passage,origin='ORIGINAL_UNSEEN')],activities=activities,coverage=dict(activityGroups=len(activities),poemQuestions=0,seenPassageQuestions=0,writingTasks=3),limitations=['Teacher review of difficulty, distractors, accepted alternatives and rubrics is pending.','This is a practice skills pack, not a certified government-format examination.','No official marks/word limits or unverified textbook page references assigned.','Textbook-based seen comprehension and poetry remain blocked on actual source reading.','Matching and rearranging sets should be reviewed for uniqueness before publication.'])
serialized=json.dumps(pack,ensure_ascii=False,indent=2)+'\n'
file=D/'original-skills-001.json'
if '--check' in sys.argv: assert file.read_text()==serialized
else: D.mkdir(parents=True,exist_ok=True);file.write_text(serialized)
# Separate student-facing tasks from teacher-facing solutions.
questions=['# Class 6 — English 1st Paper: Original Skill Practice 001','**Draft practice only — not an official model test. Marks and duration are not assigned.**','## Passage P1: Learning in the School Garden',passage]
answers=['# Answer key and assessment guidance — Practice 001','**Teacher review pending. Model writing answers are examples, not the only acceptable responses.**']
for a in activities:
 questions+=['\n## '+a['id'],a['instruction']]
 answers+=['\n## '+a['id']]
 if 'items' in a:
  for i,x in enumerate(a['items'],1):
   q=x.get('question',x.get('statement',f"{x.get('word','')}: {x.get('request','')}"));questions.append(f'{i}. {q}')
   if 'options' in x:questions += [f'   {k}. {v}' for k,v in x['options'].items()]
   ans=x.get('modelAnswer',x.get('acceptedAnswers',x.get('answer')));answers.append(f'{i}. {ans}')
   if x.get('explanation'):answers.append(x['explanation'])
   if x.get('correction'):answers.append('Correction: '+x['correction'])
 else:
  for k in ('wordBox','text','columns','rows','beginnings','endings','sentences'):
   if k in a:questions.append(json.dumps(a[k],ensure_ascii=False))
  for k in ('answers','answer','modelAnswer','explanation','assessment','note','unacceptableInferences'):
   if k in a:answers.append(k+': '+(a[k] if isinstance(a[k],str) else json.dumps(a[k],ensure_ascii=False,indent=2)))
for name,lines in [('practice-001-questions.md',questions),('practice-001-answers.md',answers)]:
 p=D/name;s='\n\n'.join(lines)+'\n'
 if '--check' in sys.argv:assert p.read_text()==s
 else:p.write_text(s)
print(f'English original skills pack: {len(activities)} activity groups, 3 writing tasks; no official marks or textbook-seen claims.')
